import cv2,numpy as np
im=cv2.imread('first_frame.png'); g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY).astype(np.float32)
Gx=cv2.Sobel(g,cv2.CV_32F,1,0,ksize=3); Gy=cv2.Sobel(g,cv2.CV_32F,0,1,ksize=3)
th=np.linspace(0,2*np.pi,72,endpoint=False); co=np.cos(th); si=np.sin(th)
res=[]
for cy in range(52,105):
 for cx in range(70,221):
  for r in range(6,18):
   xs=np.clip(np.round(cx+r*co).astype(int),0,255); ys=np.clip(np.round(cy+r*si).astype(int),0,143)
   radial=Gx[ys,xs]*co+Gy[ys,xs]*si
   # circle should have consistent sign around ring, usually edge can be any sign but magnitude
   score=np.abs(radial).mean()-0.7*np.abs(radial.mean())
   if score>60: res.append((score,cx,cy,r,np.abs(radial).mean(),radial.mean()))
res.sort(reverse=True)
out=[]
for z in res:
 sc,x,y,r,_,_=z
 if all((x-a)**2+(y-b)**2>13**2 or abs(r-c)>4 for _,a,b,c,*_ in out): out.append(z)
 if len(out)>=50: break
for z in out: print('score %.1f center %d,%d r%d mag %.1f signed %.1f'%z)
PY"
